'use strict';
let valuationData,circulationData,circulationTier='all',selectedCaseId='',selectedEdgeId='';
const flowPalette={investment:'#087454',commercial:'#315cec',finance:'#856cce',guarantee:'#b28426',noncash:'#b04e8a',supplier:'#718092'};
const flowNames={investment:'Investment',commercial:'Commercial spend',finance:'Debt / project finance',guarantee:'Guarantee',noncash:'Non-cash equity',supplier:'Supplier relationship'};
function nodeName(id){return circulationData.nodes.find(n=>n.id===id)?.name||id}
function circulationCases(){return circulationData.cases.filter(c=>circulationTier==='all'||Number(c.tier)===Number(circulationTier))}
function flowFiltered(){const q=$('#flow-query').value.toLowerCase(),type=$('#flow-type').value;return circulationData.edges.filter(e=>(circulationTier==='all'||Number(e.tier)===Number(circulationTier))&&(!type||e.flowType===type)&&(!q||[nodeName(e.from),nodeName(e.to),e.title,e.detail,e.amountLabel].join(' ').toLowerCase().includes(q)))}
function sourceMarkup(ids){return ids.map(id=>circulationData.sources[id]).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join('')}
function renderCirculation(){const cases=circulationCases();if(!cases.some(c=>c.id===selectedCaseId))selectedCaseId=cases[0]?.id||'';const active=cases.find(c=>c.id===selectedCaseId);document.querySelectorAll('[data-tier]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tier===circulationTier));$('#circulation-stats').innerHTML=[[circulationData.nodes.length,'Named counterparties'],[circulationData.edges.length,'Documented links'],[circulationData.cases.length,'Circulation & supply-chain cases'],['3','Tiers of economic exposure']].map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('');$('#case-list').innerHTML=cases.map(c=>`<button class="case-button ${c.id===selectedCaseId?'selected':''}" data-case="${esc(c.id)}"><span>TIER ${c.tier} · ${esc(c.kind)}</span><b>${esc(c.title)}</b></button>`).join('');$('#case-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedCaseId=b.dataset.case;selectedEdgeId='';renderCirculation()});if(active){$('#case-intro').innerHTML=`<span class="eyebrow">TIER ${active.tier} / ${esc(active.kind)}</span><h3>${esc(active.title)}</h3><p>${esc(active.summary)}</p>`;const edges=active.edgeIds.map(id=>circulationData.edges.find(e=>e.id===id)).filter(Boolean);if(!edges.some(e=>e.id===selectedEdgeId))selectedEdgeId=edges[0]?.id||'';renderNetwork(edges);$('#case-takeaway').innerHTML=`<p><b>What matters:</b> ${esc(active.insight)}</p><p class="small"><b>Boundary:</b> ${esc(active.limitation)}</p>`;renderEdgeDetail(selectedEdgeId)}renderFlowLedger()}
function renderNetwork(edges){const ids=[...new Set(edges.flatMap(e=>[e.from,e.to]))],N=ids.length,coords={};ids.forEach((id,i)=>{const angle=-Math.PI/2+i*2*Math.PI/N;coords[id]=[490+340*Math.cos(angle),245+180*Math.sin(angle)]});let svg='<svg viewBox="0 0 980 520" role="group" aria-label="Directed relationships in the selected money circulation case"><defs>';for(const [k,c]of Object.entries(flowPalette))svg+=`<marker id="arrow-${k}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8Z" fill="${c}"/></marker>`;svg+='</defs>';edges.forEach((e,i)=>{const [x,y]=coords[e.from],[xx,yy]=coords[e.to],dx=xx-x,dy=yy-y,len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len;const trim=1/Math.max(Math.abs(ux)/88,Math.abs(uy)/32);const a=[x+ux*trim,y+uy*trim],b=[xx-ux*trim,yy-uy*trim],pair=edges.filter(v=>[v.from,v.to].sort().join('|')===[e.from,e.to].sort().join('|')),pi=pair.findIndex(v=>v.id===e.id),bend=(pi-(pair.length-1)/2)*42*(ids.indexOf(e.from)<ids.indexOf(e.to)?1:-1);const cx=(a[0]+b[0])/2-uy*bend,cy=(a[1]+b[1])/2+ux*bend,c=flowPalette[e.flowType]||'#718092';svg+=`<path d="M${a[0]} ${a[1]} Q${cx} ${cy},${b[0]} ${b[1]}" fill="none" stroke="${c}" stroke-width="${e.id===selectedEdgeId?3.5:2}" opacity=".8" marker-end="url(#arrow-${e.flowType})"/><g class="edge-marker" role="button" tabindex="0" data-edge="${esc(e.id)}" aria-label="Link ${i+1}: ${esc(e.title)}"><circle cx="${cx}" cy="${cy}" r="15" fill="white" stroke="${c}" stroke-width="2"/><text x="${cx}" y="${cy+5}" text-anchor="middle" fill="${c}" font-size="14" font-weight="700">${i+1}</text></g>`});ids.forEach(id=>{const [x,y]=coords[id],node=circulationData.nodes.find(n=>n.id===id),name=node?.name||id;svg+=`<g class="money-node" tabindex="0" role="button" data-node="${esc(id)}" aria-label="Filter relationships for ${esc(name)}"><rect x="${x-88}" y="${y-31}" width="176" height="62" rx="7" fill="#102135"/><text x="${x}" y="${y-3}" text-anchor="middle" fill="white" font-size="${name.length>22?11:14}" font-weight="600">${esc(name)}</text><text x="${x}" y="${y+17}" text-anchor="middle" fill="#b9cbde" font-size="11">${esc(node?.ticker||node?.type||'Counterparty')}</text></g>`});$('#circulation-graph').innerHTML=svg+'</svg>';$('#circulation-graph').querySelectorAll('[data-edge]').forEach(b=>{const run=()=>{selectedEdgeId=b.dataset.edge;renderEdgeDetail(selectedEdgeId)};b.onclick=run;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}}});$('#circulation-graph').querySelectorAll('[data-node]').forEach(b=>{const run=()=>{$('#flow-query').value=nodeName(b.dataset.node);renderFlowLedger();$('#flow-count').scrollIntoView({behavior:'smooth',block:'center'})};b.onclick=run;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}}})}
function renderEdgeDetail(id){const e=circulationData.edges.find(e=>e.id===id);if(!e){$('#edge-detail').innerHTML='';return}$('#edge-detail').innerHTML=`<div><span class="eyebrow">INSPECTED LINK / TIER ${e.tier}</span><h3>${esc(nodeName(e.from))} → ${esc(nodeName(e.to))}</h3><p>${esc(e.title)}</p><span class="flow-tag" style="color:${flowPalette[e.flowType]}">${esc(flowNames[e.flowType])}</span></div><div><b class="flow-amount">${esc(e.amountLabel||'Amount not disclosed')}</b><p><b>Status:</b> ${esc(e.status)}</p><p>${esc(e.detail)}</p><p class="small">Event / agreement: ${esc(e.date||'See source')} · Evidence checked for 3 Oct 2026 snapshot.</p><div class="sources">${sourceMarkup(e.sourceIds)}</div></div>`}
function renderFlowLedger(){const rows=flowFiltered();$('#flow-count').textContent=`${rows.length} of ${circulationData.edges.length} relationships · ${circulationTier==='all'?'all tiers':'tier '+circulationTier}`;$('#flow-rows').innerHTML=rows.map(e=>`<tr><td><b>${esc(nodeName(e.from))}</b><span class="flow-direction">↓</span><b>${esc(nodeName(e.to))}</b><small>Tier ${e.tier}</small></td><td>${esc(e.title)}<small style="color:${flowPalette[e.flowType]}">${esc(flowNames[e.flowType])}</small></td><td>${esc(e.amountLabel||'Undisclosed')}<small>${esc(e.date)}</small></td><td>${esc(e.status)}</td><td><button class="evidence-button" data-inspect-edge="${esc(e.id)}">Inspect sources ↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No relationships match. Clear the filters to inspect the complete ledger.</td></tr>';$('#flow-rows').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedEdgeId=b.dataset.inspectEdge;renderEdgeDetail(selectedEdgeId);$('#edge-detail').scrollIntoView({behavior:'smooth',block:'start'})})}
function valuationRecord(c){return valuationData?.companies?.[c.ticker]||{}}
function ratio(n,suffix='×'){return Number.isFinite(n)?n.toFixed(1)+suffix:'—'}
function valuationPeriodText(v){const e=v.earnings,f=v.fcfPeriod;return `P/E = price / diluted EPS: ${e?e.basis+' '+e.start+' to '+e.end:'unavailable'}. FCF basis: ${f?f.basis+' '+f.start+' to '+f.end:'unavailable'}.`}
function debtBasisText(v){return v.debtIncludesLeases?'Reported debt basis includes or may include finance leases':'Borrowings exclude separately identified finance leases'}
function valuationFiltered(){const q=$('#valuation-query').value.toLowerCase(),focus=$('#valuation-focus').value;return companies.filter(c=>{const v=valuationRecord(c);return (!q||(c.name+' '+c.ticker).toLowerCase().includes(q))&&(focus==='all'||focus==='hidden'&&hiddenInScenario(c)||focus==='netcash'&&v.netDebt!=null&&v.netDebt<0||focus==='netdebt'&&v.netDebt>0||focus==='loss'&&val(c,'net')<0||focus==='missing'&&(v.marketCap==null||v.grossDebt==null))})}
function renderValuation(){if(!valuationData)return;const list=valuationFiltered(),sort=$('#valuation-sort').value;list.sort((a,b)=>{const x=valuationRecord(a),y=valuationRecord(b);if(sort==='pe')return (x.pe??Infinity)-(y.pe??Infinity);if(sort==='yield')return (y.fcfYield??-Infinity)-(x.fcfYield??-Infinity);if(sort==='debt')return (y.netDebtToFcf??-Infinity)-(x.netDebtToFcf??-Infinity);return a.name.localeCompare(b.name)});const all=companies.map(valuationRecord);$('#valuation-stats').innerHTML=[[all.filter(v=>v.marketCap!=null).length,'Estimated equity values'],[all.filter(v=>v.grossDebt!=null).length,'Borrowing records'],[all.filter(v=>v.pe!=null).length,'Comparable P/E ratios'],[all.filter(v=>v.netDebt<0&&v.netDebt!=null).length,'Net-cash companies']].map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('');$('#valuation-count').textContent=`${list.length} of 100 companies${$('#valuation-focus').value==='hidden'?' · '+currentScenario().short+' scenario candidates':''}`;$('#valuation-rows').innerHTML=list.map(c=>{const v=valuationRecord(c),cur=v.currency||c.currency;return `<tr><td><button class="name-button" data-company="${esc(c.ticker)}">${esc(c.name)}</button><small>${esc(c.ticker)} · ${esc(c.sector)}</small></td><td>${money(v.marketCap??null,v.marketCurrency||c.market?.currency)}<small>${v.marketCap!=null?'Approximate · dated shares':'Basis not verified'}</small></td><td>${ratio(v.pe)}<small>${v.pe==null&&val(c,'net')<=0?'Loss / not meaningful':v.ratioBasis||''}</small></td><td>${ratio(v.fcfYield,'%')}</td><td>${money(v.grossDebt??null,cur)}<small>${v.debtDate?date(v.debtDate):'Not verified'}${v.balanceStale?' · older':''}</small></td><td>${money(v.cash??null,cur)}<small>${v.cashDate?date(v.cashDate):''}</small></td><td class="${v.netDebt<0?'positive':''}">${money(v.netDebt??null,cur)}</td><td>${ratio(v.netDebtToFcf)}<small>${v.netDebtToFcf!=null?(v.debtIncludesLeases?'Includes / may include leases':'Borrowing-only basis'):''}${v.financeLeases>0&&!v.debtIncludesLeases?' · leases separate':''}</small></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No companies match these filters.</td></tr>';bindCompanies($('#valuation-rows'))}
function valuationDetail(c){const v=valuationRecord(c);if(!valuationData)return '';const cur=v.currency||c.currency;return `<section class="company-valuation"><span class="eyebrow">VALUATION & DEBT</span><h3>What the stock costs, and how it is financed</h3><div class="detail-metrics">${[['Estimated equity value',money(v.marketCap??null,v.marketCurrency||c.market?.currency)],['P/E',ratio(v.pe)],['FCF yield',ratio(v.fcfYield,'%')],['Gross borrowings',money(v.grossDebt??null,cur)],['Cash & equivalents',money(v.cash??null,cur)],['Net debt · cash only',money(v.netDebt??null,cur)],['Liquid funds incl. short-term investments',money(v.liquidFunds??null,cur)],['Borrowings + finance leases',money(v.totalDebtIncludingFinanceLeases??null,cur)]].map(([k,x])=>`<div class="detail-metric"><span>${k}</span><b>${x}</b></div>`).join('')}</div><p class="mini-label">Debt: ${date(v.debtDate)} · Cash: ${date(v.cashDate)} · Shares: ${date(v.shareDate)} · Stock price: ${date(c.market?.end)}. ${esc(valuationPeriodText(v))}</p><p>${esc(v.debtDefinition||'Debt composition not safely established.')}</p>${v.financeLeases!=null?`<p>Separately identified finance leases: ${money(v.financeLeases,cur)}. See the debt definition for inclusion treatment.</p>`:''}<p class="note">${esc((v.notes||[]).join(' '))}</p>${v.missingReasons?.length?`<p><b>Unavailable fields:</b> ${esc(v.missingReasons.join(' '))}</p>`:''}<p>Lease-adjusted net debt (cash only): ${money(v.leaseAdjustedNetDebt??null,cur)}. Lease-adjusted net debt / annual FCF: ${ratio(v.leaseAdjustedNetDebtToFcf)}.</p><p>Net debt / annual FCF: ${ratio(v.netDebtToFcf)}. ${esc(debtBasisText(v))}. This is a screening ratio, not a debt maturity or liquidity forecast.</p><div class="sources">${(v.sources||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label||s.title)}</a>`).join('')}</div><details><summary>Borrowing, cash and share inputs</summary><div class="valuation-provenance">${esc(JSON.stringify(v.components||{},null,2))}</div></details></section>`}
function companyCirculation(c){if(!circulationData)return '';const nodes=circulationData.nodes.filter(n=>n.ticker===c.ticker||n.id===c.ticker).map(n=>n.id),edges=circulationData.edges.filter(e=>nodes.includes(e.from)||nodes.includes(e.to));if(!edges.length)return '';return `<section><span class="eyebrow">MONEY CIRCULATION</span><h3>${edges.length} documented relationships in this map</h3>${edges.slice(0,8).map(e=>`<p><b>${esc(nodeName(e.from))} → ${esc(nodeName(e.to))}</b><br>${esc(e.title)} · ${esc(e.amountLabel)}<br><small>${esc(e.status)}</small></p>`).join('')}<p class="mini-label">Open Money circulation to inspect relationship sources and surrounding cases. This is a curated set, not the company’s complete counterparty book.</p></section>`}
function initExpansion(){document.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{circulationTier=b.dataset.tier;selectedCaseId='';selectedEdgeId='';renderCirculation()});$('#flow-query').oninput=renderFlowLedger;$('#flow-type').onchange=renderFlowLedger;$('#flow-reset').onclick=()=>{$('#flow-query').value='';$('#flow-type').value='';circulationTier='all';renderCirculation()};$('#valuation-query').oninput=renderValuation;$('#valuation-focus').onchange=renderValuation;$('#valuation-sort').onchange=renderValuation;$('#valuation-reset').onclick=()=>{$('#valuation-query').value='';$('#valuation-focus').value='all';$('#valuation-sort').value='name';renderValuation()};$('#valuation-method').innerHTML=(valuationData.methodology||[]).map(t=>`<p>${esc(t)}</p>`).join('');$('#flow-source-list').innerHTML=Object.entries(circulationData.sources).map(([id,s])=>`<article>${sourceMarkup([id])}</article>`).join('');document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>downloadResearchReport(b.dataset.report));renderCirculation();renderValuation()}
